// Compressed geometry: no font installation, Fontconfig, Pango or network needed.
import { inflateSync } from 'node:zlib';
type Face = { units: number; glyphs: Record<string, [number, string]> };
const faces = JSON.parse(inflateSync(Buffer.from("", 'base64')).toString()) as Record<string, Face>;
export function outlineText(x:number,y:number,value:string,size=24,fill='#f2f4ff',weight=400,maxWidth=0) {
  const face=faces[weight >= 600 ? 'bold' : 'regular'];
  const chars=Array.from(value.normalize('NFC'));
  const glyphs=chars.map(c=>face.glyphs[c] ?? face.glyphs['�']);
  const scale=size/face.units;
  const advance=glyphs.reduce((sum,g)=>sum+g[0],0);
  const sx=maxWidth && advance*scale>maxWidth ? maxWidth/advance : scale;
  let cursor=0;
  const paths=glyphs.map(([width,path])=>{const out=path ? `<path transform="translate(${cursor} 0)" d="${path}"/>` : '';cursor+=width;return out;}).join('');
  return `<g fill="${fill}" transform="translate(${x} ${y}) scale(${sx} ${-scale})">${paths}</g>`;
}
